import { animate, AnimatePresence, motion } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';
import { PROGRESS_RULES } from '../../progression/progression';
import type { ShownProgress } from '../useTable';

/*
 * Both meters are layer-by-layer ports of the supplied SVGs (design-source/blackjack-meters,
 * generated by _generator.py): same geometry, colours, gradients, clip path, glow filter and flame
 * paths. Only the parts that change are live — the fill height, the badge state and the value text
 * (outlined glyphs in the SVG, live Roboto Slab 800 text here).
 */
const CREAM = '#FEFDD4', PANEL = '#15171D', EDGE = '#3A3D47', TRACK = '#2A2D36';
const FLAME = 'M0,-46 C14,-26 34,-14 34,10 C34,32 18,46 0,46 C-18,46 -34,32 -34,10 C-34,-6 -24,-16 -16,-26 C-14,-14 -8,-8 -2,-6 C-6,-22 -4,-36 0,-46 Z';
const FLAME_CORE = 'M0,6 C8,15 14,21 14,29 C14,38 8,44 0,44 C-8,44 -14,38 -14,29 C-14,21 -6,15 0,6 Z';

function useCount(value: number, duration = 0.5) {
  const [v, setV] = useState(value);
  const from = useRef(value);
  useEffect(() => {
    const c = animate(from.current, value, { duration, ease: 'easeOut', onUpdate: x => setV(Math.round(x)) });
    from.current = value;
    return () => c.stop();
  }, [value, duration]);
  return v;
}

// ---------------- Nerve XP pill (nerve-xp-pill-*.svg, scaled 48 → 32px tall) ----------------
function starPath(cx: number, cy: number, ro: number, ri: number) {
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const r = i % 2 === 0 ? ro : ri;
    const a = ((-90 + i * 36) * Math.PI) / 180;
    pts.push(`${(cx + r * Math.cos(a)).toFixed(2)},${(cy + r * Math.sin(a)).toFixed(2)}`);
  }
  return `M${pts.join(' L')} Z`;
}

/** Nerve total; the inner fill shows progress toward unlocking Fever (300), full once unlocked. */
export function XpMeter({ nerve, unlocked }: { nerve: number; unlocked: boolean }) {
  const shown = useCount(nerve, 0.6);
  const frac = unlocked ? 1 : Math.min(1, nerve / PROGRESS_RULES.feverUnlockAt);
  return (
    <div className="xp-meter" aria-label={`Nerve XP ${nerve}`} data-value={nerve}>
      <motion.span className="xp-fill" initial={false} animate={{ width: `${frac * 100}%` }} transition={{ type: 'spring', stiffness: 120, damping: 22 }} />
      {nerve > 0 && <motion.span key={`glow-${nerve}`} className="xp-glow" initial={{ opacity: 1 }} animate={{ opacity: 0 }} transition={{ duration: 0.8 }} />}
      <svg className="xp-badge" width="26" height="26" viewBox="0 0 38 38" aria-hidden>
        <defs><linearGradient id="xp-badge" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#2EE6C5" /><stop offset="1" stopColor="#1F8FFF" /></linearGradient></defs>
        <circle cx="19" cy="19" r="19" fill="url(#xp-badge)" />
        <path fill={CREAM} d={starPath(19, 20, 10.5, 4.5)} />
      </svg>
      <motion.span key={nerve} className="xp-num" initial={{ scale: 1.25 }} animate={{ scale: 1 }}>{shown.toLocaleString('en-US')}</motion.span>
      <span className="xp-unit">XP</span>
    </div>
  );
}

// ---------------- Fever meter (fever-meter-*.svg, 80×268) ----------------
const IN_X = 30, IN_W = 20, IN_Y0 = 70, IN_Y1 = 222;

export type FeverVisual = 'filling' | 'ready' | 'active';

export function feverVisual(p: ShownProgress): FeverVisual {
  if (p.roundsLeft > 0) return 'active';
  return p.meter >= PROGRESS_RULES.feverMeterSize ? 'ready' : 'filling';
}

/** Fever meter. Filling → asset's empty/half look; ready → asset's full look with pulsing glow;
 *  active → full look with a flickering flame, draining one third per Fever round. */
export function FeverMeter({ p, onTap }: { p: ShownProgress; onTap?: () => void }) {
  const state = feverVisual(p);
  const size = PROGRESS_RULES.feverMeterSize;
  const meter = Math.min(p.meter, size);
  const frac = state === 'active' ? p.roundsLeft / PROGRESS_RULES.feverRounds : state === 'ready' ? 1 : meter / size;
  const fh = (IN_Y1 - IN_Y0) * frac;
  const hot = state !== 'filling';
  const badge = hot ? 'full' : meter > 0 ? 'half' : 'empty';
  const label = state === 'active' ? `${p.roundsLeft} LEFT` : state === 'ready' ? 'READY' : `${Math.round(meter)}/${size}`;
  const shownMeter = useCount(meter, 0.5);
  const text = state === 'filling' ? `${shownMeter}/${size}` : label;

  return (
    <motion.button className="fever-meter" onClick={onTap} disabled={!onTap} aria-label={`Fever meter: ${label}`}
      initial={{ scale: 0.4, opacity: 0, y: -20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.4, opacity: 0 }}
      transition={{ type: 'spring', stiffness: 220, damping: 18 }}>
      <svg width="56" height="188" viewBox="0 0 80 268">
        <defs>
          <linearGradient id="fv-fill" gradientUnits="userSpaceOnUse" x1="0" y1={IN_Y1} x2="0" y2={IN_Y0}>
            <stop offset="0" stopColor="#FFD23F" /><stop offset=".55" stopColor="#FF8A1F" /><stop offset="1" stopColor="#F0442C" />
          </linearGradient>
          <linearGradient id="fv-badge" x1="0" y1="1" x2="0" y2="0"><stop offset="0" stopColor="#FF8A1F" /><stop offset="1" stopColor="#F0442C" /></linearGradient>
          <clipPath id="fv-clip"><rect x={IN_X} y={IN_Y0} width={IN_W} height={IN_Y1 - IN_Y0} rx="10" /></clipPath>
          <filter id="fv-glow" x="-50%" y="-20%" width="200%" height="140%"><feGaussianBlur stdDeviation="6" /></filter>
        </defs>

        {/* glow behind tube + badge (asset: full state only) */}
        <AnimatePresence>
          {hot && (
            <motion.g key="glow" filter="url(#fv-glow)" aria-hidden
              initial={{ opacity: 0 }} exit={{ opacity: 0 }}
              animate={{ opacity: state === 'active' ? [0.6, 1, 0.6] : [0.45, 0.85, 0.45] }}
              transition={{ duration: state === 'active' ? 0.9 : 1.8, repeat: Infinity, ease: 'easeInOut' }}>
              <rect x="26" y="52" width="28" height="174" rx="14" fill="#FF7A1A" />
              <circle cx="40" cy="34" r="26" fill="#FF7A1A" />
            </motion.g>
          )}
        </AnimatePresence>

        {/* tube + track */}
        <rect x="26" y="52" width="28" height="174" rx="14" fill={PANEL} stroke={hot ? '#FF8A1F' : EDGE} strokeWidth="2" style={{ transition: 'stroke 300ms' }} />
        <rect x={IN_X} y={IN_Y0} width={IN_W} height={IN_Y1 - IN_Y0} rx="10" fill={TRACK} />

        {/* fill (live) */}
        <g clipPath="url(#fv-clip)">
          <motion.rect x={IN_X} width={IN_W} fill="url(#fv-fill)" initial={false}
            animate={{ y: IN_Y1 - fh, height: fh }} transition={{ type: 'spring', stiffness: 90, damping: 18 }} />
          <motion.rect x={IN_X + 4} width="4" rx="2" fill="#FFFFFF" opacity=".28" initial={false}
            animate={{ y: IN_Y1 - fh + 4, height: Math.max(fh - 8, 0) }} transition={{ type: 'spring', stiffness: 90, damping: 18 }} />
        </g>

        {/* segment dividers every 10 points */}
        {[1, 2, 3, 4].map(i => {
          const y = IN_Y0 + ((IN_Y1 - IN_Y0) / 5) * i;
          return <line key={i} x1={IN_X} y1={y} x2={IN_X + IN_W} y2={y} stroke={PANEL} strokeWidth="2" />;
        })}

        {/* flame badge: empty / half / full looks from the asset */}
        <circle cx="40" cy="34" r="26" fill={badge === 'full' ? 'url(#fv-badge)' : PANEL}
          stroke={badge === 'full' ? '#FFD23F' : badge === 'half' ? '#FF8A1F' : EDGE} strokeWidth="2" />
        <motion.g style={{ originX: '40px', originY: '33px' }}
          animate={state === 'active' ? { scale: [1, 1.12, 0.96, 1.08, 1], rotate: [0, -3, 2, -1, 0] } : { scale: 1, rotate: 0 }}
          transition={state === 'active' ? { duration: 0.8, repeat: Infinity, ease: 'easeInOut' } : { duration: 0.3 }}>
          <path transform="translate(40 33) scale(.32)" fill={badge === 'full' ? CREAM : badge === 'half' ? '#FF8A1F' : '#5A5E6B'} d={FLAME} />
          <path transform="translate(40 33) scale(.32)" fill={badge === 'full' ? '#FFB020' : PANEL} d={FLAME_CORE} />
        </motion.g>

        {/* value pill */}
        <rect x="8" y="236" width="64" height="26" rx="13" fill={PANEL} stroke={hot ? '#FF8A1F' : EDGE} strokeWidth="1.5" />
        <text x="40" y="253.5" textAnchor="middle" fill={CREAM} fontFamily="'Roboto Slab', serif" fontWeight="800"
          fontSize={hot ? 12 : 13} letterSpacing={hot ? 0.3 : 0}>{text}</text>
      </svg>
    </motion.button>
  );
}
